// Parse Gemini response — extract JSON from the text output
const items = $input.all();
const results = [];

for (const item of items) {
  try {
    const candidates = item.json?.candidates || [];
    const text = candidates[0]?.content?.parts?.[0]?.text || '';

    // Try to parse the JSON directly
    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch {
      // Try to extract JSON from markdown code blocks
      const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (jsonMatch) {
        parsed = JSON.parse(jsonMatch[1].trim());
      } else {
        // Try to find JSON object in the text
        const objMatch = text.match(/\{[\s\S]*\}/);
        if (objMatch) {
          parsed = JSON.parse(objMatch[0]);
        } else {
          throw new Error('No JSON found in Gemini response');
        }
      }
    }

    // Validate required fields
    results.push({
      json: {
        intent: parsed.intent || 'inquiry',
        reply: parsed.reply || 'عذراً، لم أتمكن من فهم طلبك. يرجى إعادة الصياغة.',
        proposedAction: parsed.proposedAction || null,
        success: true
      }
    });
  } catch (err) {
    results.push({
      json: {
        intent: 'error',
        reply: 'مرحباً! نعتذر عن التأخير — يمكنك التواصل مباشرة مع الصالون. 🙏',
        proposedAction: null,
        success: false,
        error: err.message
      }
    });
  }
}

return results;
